--TAULA client_locations
SELECT 
	TRIM(REPLACE(id_client_location,CHAR(160),' ')) AS id_client_location,
	TRIM(REPLACE(name,CHAR(160),' ')) AS name,
	active,
	TRIM(REPLACE(address,CHAR(160),' ')) AS address,
	TRIM(REPLACE(city,CHAR(160),' ')) AS city,
	TRIM(REPLACE(zip_code,CHAR(160),' ')) AS zip_code,
	TRIM(REPLACE(country_code,CHAR(160),' ')) AS country_code,
	salesmen_id,
	(  CASE
		  WHEN new_code IS NULL 
		  THEN NULL
		  ELSE concat(TRIM(REPLACE(new_code,CHAR(160),' ')) ,'-000')
		END
	) AS new_code,
	TRIM(REPLACE(phone_number,CHAR(160),' ')) AS phone_number,
	TRIM(REPLACE(email,CHAR(160),' ')) AS email
FROM est_clients 
WHERE id_client_location <> '';
	
--TAULA products
SELECT 
	TRIM(REPLACE(id_product,CHAR(160),' ')) AS id_product,
	TRIM(REPLACE(name,CHAR(160),' ')) AS name,
	TRIM(REPLACE(product_categories_id,CHAR(160),' ')) AS product_categories_id,
	CASE
		WHEN active = 'True' THEN 1
		ELSE 0
	END as active
 FROM est_productes
