--TAULA product_categories
SELECT 
	TRIM(REPLACE(id_product_category,CHAR(160),' ')) AS id_product_category,
	' ' AS name
 FROM est_families_productes where id_product_category <> ''
 group by id_product_category, name;
	
	
--TAULA salesmen
SELECT * FROM est_agents;

--TAULA invoice_lines
SELECT
	id_invoice_line,
	invoices_id,
	CAST(date AS DATE) AS date,
	TRIM(REPLACE(client_locations_id,CHAR(160),' ')) AS client_locations_id,
	TRIM(REPLACE(products_id,CHAR(160),' ')) AS products_id,
	product_price/100 as product_price,
	product_cost/100 as product_cost,
	net_amount as net_amount,
	1-discount as discount,
	quantity,
	series,
	observations
 FROM est_linies_albara
 WHERE series not in ('06','11','16','27','36','46','18')
 AND year(date)>=2019
 and DATEDIFF(DAY, date, GETDATE()) <= 90
 AND client_locations_id NOT LIKE '00321540-%'
 AND client_locations_id NOT LIKE '00273137-%'
