--TAULA atributs de client (aquí obtenim tots els diferents atributs de la taula per generar l'estructura que esperem)
-- RAÓ SOCIAL
WITH MyTest AS 
	(
		SELECT  id_client_location, p.new_code, CONCAT(LEFT(REPLACE(p.id_client_location,CHAR(160),' '),charindex('-', REPLACE(p.id_client_location,CHAR(160),' '))-1), ' ', TRIM(REPLACE(p.name,CHAR(160),' '))) as value
		FROM    est_clients p
		WHERE   p.new_code is null -- this condition defines the ultimate ancestors in your chain, change it as appropriate
		UNION ALL
		SELECT  p1.id_client_location, p1.new_code, m.value
		FROM    est_clients p1
		INNER JOIN MyTest m
		ON m.id_client_location = concat(p1.new_code,'-000')
	)
SELECT TRIM(REPLACE(id_client_location,CHAR(160),' ')) AS client_locations_id,
'RAÓ SOCIAL' as name,
value
FROM MyTest
UNION
-- ZONA
(
	SELECT
		TRIM(REPLACE(client_locations_id,CHAR(160),' ')) AS client_locations_id,
		'ZONA' as name,
		TRIM(REPLACE(zone_description,CHAR(160),' ')) as value
	FROM est_atributs_client
	WHERE TRIM(REPLACE(client_locations_id,CHAR(160),' ')) <> ''
)            
UNION
-- positioning_bcn_consulting
(
	SELECT
		TRIM(REPLACE(client_locations_id,CHAR(160),' ')) AS client_locations_id,
		'POS. BCN CONSULTING' as name,
		TRIM(REPLACE(positioning_bcn_consulting,CHAR(160),' ')) as value
	FROM est_atributs_client
	WHERE TRIM(REPLACE(client_locations_id,CHAR(160),' ')) <> ''
)
UNION
-- actiu
(
	SELECT
		TRIM(REPLACE(id_client_location,CHAR(160),' ')) AS client_locations_id,
		'ACTIU' as name,
		CASE 
			WHEN active = 0 THEN 'No'
			WHEN active = 1 THEN 'Si'
		END
		as value
	FROM est_clients
	WHERE TRIM(REPLACE(id_client_location,CHAR(160),' ')) <> ''
)
UNION
-- SEGMENT US FARINA 1
(
   SELECT
		TRIM(REPLACE(client_locations_id,CHAR(160),' ')) AS client_locations_id,
		'SEGMENT US FARINA 1' as name,
		TRIM(REPLACE(segmentation_use_1,CHAR(160),' ')) as value
	FROM est_atributs_client
	WHERE TRIM(REPLACE(client_locations_id,CHAR(160),' ')) <> ''
)
UNION
-- SEGMENT US FARINA 2
(
   SELECT
		TRIM(REPLACE(client_locations_id,CHAR(160),' ')) AS client_locations_id,
		'SEGMENT US FARINA 2' as name,
		TRIM(REPLACE(segmentation_use_2,CHAR(160),' ')) as value
	FROM est_atributs_client
	WHERE TRIM(REPLACE(client_locations_id,CHAR(160),' ')) <> ''
)
; 

--TAULA atributs producte
SELECT 
	TRIM(REPLACE(art_codi,CHAR(160),' ')) as products_id,
	'SUBFAMILIA' as name,
	TRIM(REPLACE(subfamily_description,CHAR(160),' ')) as value
FROM est_atributs_producte;